package com.sibcraft.creeperborn;
import java.util.*;
import java.nio.file.*;
import com.google.gson.GsonBuilder;
import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.networking.v1.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.entity.*;
import net.minecraft.world.phys.Vec3;
/** Two real login-protocol clients, real PlayerList, tracking, Fabric packets and reconnect lifecycle. Offline names are CI-only. */
public final class MultiplayerServer implements ModInitializer {
 private MinecraftServer server;private int ticks,stage,age;private long started;private UUID betaId;private ServerPlayer oldBeta;private boolean prepared;
 private final Set<UUID> completed=new HashSet<>();
 private final Map<UUID,MultiplayerProbe> samples=new HashMap<>();private final List<String> passed=new ArrayList<>();private final List<Double> durations=new ArrayList<>();private double flightError,dragonError;
 public void onInitialize(){if(!Boolean.getBoolean("creeperborn.multiplayer"))return;PayloadTypeRegistry.clientboundPlay().register(MultiplayerProbe.TYPE,MultiplayerProbe.CODEC);PayloadTypeRegistry.serverboundPlay().register(MultiplayerProbe.TYPE,MultiplayerProbe.CODEC);
  ServerPlayNetworking.registerGlobalReceiver(MultiplayerProbe.TYPE,(p,ctx)->{if(p.action()==2&&p.stage()==9)completed.add(ctx.player().getUUID());if(p.action()==1&&Double.isFinite(p.x())&&Double.isFinite(p.y())&&Double.isFinite(p.z()))samples.put(ctx.player().getUUID(),p);});
  ServerLifecycleEvents.SERVER_STARTED.register(s->{server=s;Creeperborn.config().naturalCreepers=false;System.out.println("CREEPERBORN_MULTIPLAYER_SERVER_READY");});
  ServerTickEvents.START_SERVER_TICK.register(s->started=System.nanoTime());ServerTickEvents.END_SERVER_TICK.register(s->{if(server==null)return;durations.add((System.nanoTime()-started)/1_000_000.0);try{run();}catch(Throwable e){e.printStackTrace();write(false,e.toString());server=null;s.halt(false);}});
 }
 private void check(boolean b,String text){if(!b)throw new AssertionError(text);passed.add(text);System.out.println("MULTIPLAYER_CHECK "+text);}
 private ServerPlayer find(String name){return server.getPlayerList().getPlayers().stream().filter(p->p.getGameProfile().name().equals(name)).findFirst().orElse(null);}
 private void command(ServerPlayer a,ServerPlayer b,int next){stage=next;age=0;samples.clear();for(var p:List.of(a,b))ServerPlayNetworking.send(p,MultiplayerProbe.command(next,p==a?b.getId():a.getId()));}
 private boolean reports(int n){return samples.size()==2&&samples.values().stream().allMatch(q->q.stage()==stage&&q.tick()>=n);}
 private void clean(ServerPlayer p){FruitClaims.releaseOnDeath(p);p.removeAllEffects();p.setAbsorptionAmount(0);p.setHealth(p.getMaxHealth());p.getFoodData().setFoodLevel(20);p.addTag("cb_mode_fruit");}
 private void place(ServerPlayer p,double x,double z){p.teleportTo(server.overworld(),x,121,z,Set.of(),0,0,false);p.setGameMode(GameType.SURVIVAL);p.getFoodData().setFoodLevel(20);p.setHealth(p.getMaxHealth());}
 private void celestial(ServerPlayer p,String f){check(CelestialPowers.consume(p,Relics.celestialFruit(f),f),"Native player consumes "+f);CelestialPowers.grant(p,f,3);}
 private double error(ServerPlayer p){var q=samples.get(p.getUUID());return p.position().distanceTo(new Vec3(q.x(),q.y(),q.z()));}
 private void run(){ticks++;age++;if(stage==9&&age>60&&completed.size()==2){var stop=server;server=null;stop.halt(false);return;}if(stage==9&&age>600)throw new AssertionError("Native clients did not acknowledge completion");if(ticks>6500)throw new AssertionError("Multiplayer scenario timeout at stage "+stage);ServerPlayer a=find("LanAlpha"),b=find("LanBeta");for(var p:server.getPlayerList().getPlayers())p.getFoodData().setFoodLevel(20);
  if(stage==0){if(a==null||b==null||!ServerPlayNetworking.canSend(a,MultiplayerProbe.TYPE)||!ServerPlayNetworking.canSend(b,MultiplayerProbe.TYPE))return;var l=server.overworld();for(int x=-4;x<=3;x++)for(int z=-2;z<=8;z++)l.setChunkForced(x,z,true);for(int x=-20;x<=20;x++)for(int z=-10;z<=30;z++)l.setBlock(new BlockPos(x,120,z),Blocks.STONE.defaultBlockState(),3);clean(a);clean(b);place(a,-4,0);place(b,4,0);celestial(a,"glint");celestial(b,"flame");check(server.getPlayerList().getPlayerCount()==2&&a.connection!=null&&b.connection!=null,"Two distinct native clients joined real dedicated PlayerList and negotiated Fabric payloads");CelestialPowers.cast(a,"glint",2,20);CelestialPowers.cast(b,"flame",1,20);CelestialPowers.cast(b,"flame",2,20);command(a,b,1);return;}
  if(stage==3){if(b==null)return;if(b==oldBeta)return;check(b.getUUID().equals(betaId)&&CelestialPowers.unlocked(b,"straw"),"Disconnected native client rejoins with same identity and persisted fruit ownership");check(CelestialPowers.linkCount(b)==0&&!CelestialPowers.form(b),"Reconnect does not restore stale effigies or transformation");place(b,a.getX()+8,a.getZ());command(a,b,4);return;}
  if(a==null||b==null)return;
  if(stage==1&&reports(145)){check(samples.values().stream().allMatch(q->q.peer()>0),"Each native client tracks the other player entity after crossing chunks");check(samples.values().stream().allMatch(q->q.displays()>=0),"Native chunk streams follow custom flight across chunk boundaries");flightError=Math.max(error(a),error(b));check(flightError<1.5,"Light and Flame flight settle within 1.5 blocks of native client positions under latency; measured "+flightError);var sa=samples.get(a.getUUID());var sb=samples.get(b.getUUID());check((sa.celestial()&7)==5&&(sb.celestial()&2053)==2053,"Both native clients receive their own active flight flags");check((sa.otherCelestial()&2053)==2053&&(sb.otherCelestial()&7)==5,"Remote observers receive other player's correct transformation and spear flags");check(a.getZ()>40&&b.getZ()>40,"Both players cross chunk boundaries while flying");clean(a);clean(b);place(a,-4,0);place(b,-4,10);celestial(a,"buddha");celestial(b,"straw");CelestialPowers.cast(a,"buddha",2,20);b.setYRot(180);check(CelestialPowers.cast(b,"straw",1,0).contains("Bound"),"Straw binds an actual connected player rather than a fake actor");command(a,b,2);return;}
  if(stage==2&&reports(75)){var sa=samples.get(a.getUUID());var sb=samples.get(b.getUUID());check((sa.celestial()&4100)==4100&&(sb.otherCelestial()&4100)==4100,"Buddha owner and remote client agree on giant form");check(((sa.otherCelestial()>>4)&15)==1&&((sb.celestial()>>4)&15)==1,"Effigy count synchronizes to caster and observer");float bh=b.getHealth(),ward=a.getAbsorptionAmount();b.damageCooldownTime=0;b.hurtServer(server.overworld(),a.damageSources().playerAttack(a),10);check(b.getHealth()==bh&&a.getAbsorptionAmount()<ward,"Native PvP damage transfers from Straw owner into linked Buddha protective health");betaId=b.getUUID();oldBeta=b;command(a,b,3);b.connection.disconnect(Component.literal("Creeperborn CI reconnect check"));return;}
  if(stage==4&&reports(75)){check((samples.get(b.getUUID()).otherCelestial()&4100)==4100,"Rejoined observer receives already-active giant form");check(((samples.get(b.getUUID()).celestial()>>4)&15)==0,"Rejoined client HUD has no stale effigy count");clean(a);clean(b);place(a,-4,0);place(b,4,0);check(Azure.consume(a,Relics.azureFruit()),"Native Azure owner consumes fruit");Azure.grant(a,3);check(NaturePowers.consume(b,Relics.natureFruit("petal"),"petal"),"Native Petal owner consumes fruit");NaturePowers.grant(b,"petal",3);Azure.cast(a,2,20);NaturePowers.cast(b,"petal",2,20);command(a,b,5);return;}
  if(stage==5&&reports(145)){dragonError=Math.max(error(a),error(b));check(dragonError<.35,"Dragon and Demonio flight settle within 0.35 blocks of native clients; measured "+dragonError);check((samples.get(b.getUUID()).otherAzure()&3)==2&&(samples.get(a.getUUID()).otherNature()&12)==12,"Remote clients observe long dragon and Demonio forms");check(samples.values().stream().anyMatch(q->q.displays()>8),"Native client tracks custom body/visual display entities");Azure.cast(a,1,20);NaturePowers.cast(b,"petal",0,20);command(a,b,6);return;}
  if(stage==6&&reports(100)){clean(a);clean(b);command(a,b,7);return;}
  if(stage==7&&reports(85)){check(samples.values().stream().allMatch(q->q.celestial()==0&&q.otherCelestial()==0&&(q.azure()&3)==0&&(q.otherAzure()&3)==0&&q.nature()==0&&q.otherNature()==0),"Both clients clear all remote and local transformation state after cleanup");check(Azure.shotCount()==0&&Azure.proxyCount()==0&&CelestialPowers.powerShotCount()==0,"Server clears outgoing projectiles and dragon hitboxes");place(a,-10,0);place(b,10,0);check(ZoanPowers.consume(a,Relics.zoanFruit("fox"),"fox")&&ZoanPowers.consume(b,Relics.zoanFruit("axolotl"),"axolotl"),"Native clients consume both Zoan fruits");ZoanPowers.grant(a,"fox",3);ZoanPowers.grant(b,"axolotl",3);command(a,b,8);return;}
  if(stage==8&&reports(145)){check((samples.get(a.getUUID()).zoan()&15)==9&&(samples.get(b.getUUID()).otherZoan()&15)==9,"Golden Cloak synchronizes to owner and remote observer");check((samples.get(b.getUUID()).zoan()&15)==14&&(samples.get(a.getUUID()).otherZoan()&15)==14,"Giant Axolotl synchronizes to both clients");check(error(a)<1.5&&a.getZ()>25,"Golden Cloak uses native flight across chunks under latency");place(a,-10,0);place(b,10,0);check(ZoanPowers.cast(a,"fox",1,20).contains("Nine-Tails"),"Native Golden Cloak switches into grounded full fox");check(ZoanPowers.cast(b,"axolotl",2,20).contains("Small Axolotl"),"Native giant switches into small swimmer");for(int x=6;x<=14;x++)for(int z=-2;z<=50;z++)for(int y=121;y<=124;y++)server.overworld().setBlock(new BlockPos(x,y,z),Blocks.WATER.defaultBlockState(),3);command(a,b,10);return;}
  if(stage==10&&age==35){check(ZoanPowers.cast(a,"fox",1,0).contains("25 blocks"),"Native full fox launches jump dash");}
  if(stage==10&&reports(110)){check((samples.get(b.getUUID()).otherZoan()&15)==13&&(samples.get(a.getUUID()).otherZoan()&15)==6,"Both observers receive full fox and small Axolotl forms");check(Math.abs(a.getZ()-25)<1&&error(a)<1.5&&!a.getAbilities().mayfly,"Full-fox 25-block dash settles correctly on the real client without flight");check(b.getZ()>12&&WaterRules.aquatic(b)&&b.getAirSupply()>200,"Native small Axolotl swims quickly without drowning");clean(a);clean(b);command(a,b,11);return;}
  if(stage==11&&reports(65)){check(samples.values().stream().allMatch(q->q.zoan()==0&&q.otherZoan()==0),"Both native clients clear Zoan form and dimensions after cleanup");check(!a.getAbilities().mayfly&&Math.abs(a.getBbHeight()-1.8)<.01&&Math.abs(b.getBbHeight()-1.8)<.01,"Native cleanup restores ordinary flight permissions and collision boxes");command(a,b,9);write(true,"");System.out.println("CREEPERBORN_NATIVE_MULTIPLAYER_PASSED");prepared=true;return;}
  if(stage==9&&age>60&&completed.size()==2){server=null;a.level().getServer().halt(false);}
 }
 private void write(boolean success,String failure){try{var sorted=new ArrayList<>(durations);Collections.sort(sorted);var report=new LinkedHashMap<String,Object>();report.put("passed",success);report.put("checks",passed);report.put("failure",failure);report.put("native_clients",2);report.put("transport","real TCP, offline test identities, Fabric payload negotiation; loopback delay set by CI");report.put("flight_error_blocks",flightError);report.put("dragon_demonio_error_blocks",dragonError);report.put("server_tick_p50_ms",sorted.get(sorted.size()/2));report.put("server_tick_p95_ms",sorted.get((int)(sorted.size()*.95)));report.put("performance_note","CI software-rendered clients share CPU; not a production hardware benchmark");Files.writeString(Path.of("multiplayer-report.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));}catch(Exception e){throw new RuntimeException(e);}}
}
